import React from 'react';
import './Jubilacion.css';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

// Datos simulados del precio del dólar durante la semana
const data = [
    { name: 'Lun', price: 18.5 }, // Precio inicial
    { name: 'Mar', price: 18.7 }, // Subida el martes
    { name: 'Mié', price: 18.6 }, // Caída ligera el miércoles
    { name: 'Jue', price: 18.8 }, // Subida el jueves
    { name: 'Vie', price: 19.0 }, // Subida el viernes
    { name: 'Sáb', price: 19.1 }, // Subida ligera el sábado
    { name: 'Dom', price: 18.9 }, // Caída el domingo
];

const Jubilacion = () => {
    return (
        <div className="jubilacion-container">
            <h1 className="jubilacion-title">Predicción de Moneda</h1>
            <div className="jubilacion-content">
                <p>Este es un espacio para agregar contenido relevante sobre la predicción de moneda.</p>

                <h2>Tendencia del Precio del Dólar</h2>
                <div className="chart-wrapper">
                    <ResponsiveContainer width="100%" height={300}>
                        <LineChart data={data}>
                            <CartesianGrid strokeDasharray="3 3" />
                            <XAxis dataKey="name" />
                            <YAxis domain={[18, 19.5]} /> {/* Rango ajustado para la escala del dólar */}
                            <Tooltip />
                            <Legend />
                            <Line type="monotone" dataKey="price" stroke="#8884d8" activeDot={{ r: 8 }} />
                        </LineChart>
                    </ResponsiveContainer>
                </div>

                <h2>Detalles Adicionales</h2>
                <div className="highlight">
                    <p>Información destacada o notas importantes.</p>
                </div>

                <div className="button-container">
                    <button className="circular-button comprar-button">Comprar</button>
                    <button className="circular-button vender-button">Vender</button>
                </div>
            </div>
        </div>
    );
};

export default Jubilacion;
